        String sql = "INSERT INTO messages (channel, destination, subject, body) VALUES (?, ?, ?, ?)";

        try (Connection conn = database.getConnection();
             var stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

